"""Tests for the Ray job driver generated by RayCodeGen.

The snapshot tests in test_task_codegen.py pin the exact text; these check
properties the snapshots cannot: the driver compiles for 1- and N-node
tasks, and the per-node task runner -- pickled by value and executed by Ray
workers on every node -- never imports sky.
"""
import builtins
import dis
import json
import os
import subprocess
import sys
import textwrap
import types
from typing import List, Set

import pytest

from sky.backends import task_codegen

_REPO_ROOT = os.path.dirname(
    os.path.dirname(
        os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))))

# Functions the generated driver hands to Ray workers (directly or as a
# global of the remote function, which cloudpickle ships by value too).
_PER_NODE_FUNCTIONS = ('run_task_script_with_log_and_return_pid',
                       '_start_subprocess_daemon')
# Stdlib modules the per-node functions may use. Each must be imported by
# the generated driver (checked below).
_ALLOWED_MODULES = ('importlib', 'io', 'os', 'signal', 'subprocess', 'sys',
                    'tempfile')


def _build_driver(num_nodes: int, with_setup: bool) -> str:
    codegen = task_codegen.RayCodeGen()
    codegen.add_prologue(job_id=5)
    ips = [f'10.0.0.{i + 1}' for i in range(num_nodes)]
    codegen.add_setup(num_nodes,
                      resources_dict={
                          'CPU': 0.5,
                          'GPU': 1.0
                      },
                      stable_cluster_internal_ips=ips,
                      env_vars={'FOO': 'a b'},
                      log_dir='~/sky_logs/sky-test',
                      setup_cmd='echo setup' if with_setup else None)
    codegen.add_task(num_nodes,
                     bash_script='echo rank $SKYPILOT_NODE_RANK',
                     task_name='t',
                     resources_dict={
                         'CPU': 0.5,
                         'GPU': 1.0
                     },
                     log_dir='~/sky_logs/sky-test/tasks',
                     env_vars={'FOO': 'a b'})
    codegen.add_epilogue()
    return codegen.build()


def _code_objects(code: types.CodeType) -> List[types.CodeType]:
    found = [code]
    for const in code.co_consts:
        if isinstance(const, types.CodeType):
            found.extend(_code_objects(const))
    return found


def _globals_loaded(code: types.CodeType) -> Set[str]:
    """Global names read by the function, including nested code objects."""
    names = set()
    for obj in _code_objects(code):
        for instr in dis.get_instructions(obj):
            if instr.opname in ('LOAD_GLOBAL', 'LOAD_NAME'):
                names.add(instr.argval)
    return names


@pytest.mark.parametrize('num_nodes', [1, 4])
@pytest.mark.parametrize('with_setup', [True, False])
def test_driver_compiles(num_nodes, with_setup):
    code = _build_driver(num_nodes, with_setup)
    compile(code, f'driver_{num_nodes}', 'exec')
    # One remote call per node, plus the setup fan-out.
    assert code.count(
        'futures.append(run_task_script_with_log_and_return_pid') == num_nodes
    assert ('setup_workers = [run_task_script_with_log_and_return_pid'
            in code) == with_setup


@pytest.mark.parametrize('num_nodes', [1, 4])
def test_per_node_functions_use_only_stdlib_globals(num_nodes):
    """Static check: the per-node functions read no sky-bound globals."""
    code = _build_driver(num_nodes, with_setup=True)
    module = compile(code, 'driver', 'exec')
    by_name = {
        c.co_name: c
        for c in _code_objects(module)
        if c.co_name in _PER_NODE_FUNCTIONS
    }
    assert set(by_name) == set(_PER_NODE_FUNCTIONS)
    allowed = (set(dir(builtins)) | set(_ALLOWED_MODULES) |
               set(_PER_NODE_FUNCTIONS))
    for name, fn_code in by_name.items():
        offenders = _globals_loaded(fn_code) - allowed
        assert not offenders, (name, offenders)
    # Every module those functions use is bound by a stdlib import in the
    # driver (and never rebound by a `from sky...` import).
    lines = code.splitlines()
    for mod in _ALLOWED_MODULES:
        assert any(line == f'import {mod}' or line.startswith(f'import {mod}.')
                   for line in lines), mod
    assert not any(
        line.startswith('from sky') and
        line.endswith(tuple(f'import {mod}'
                            for mod in _ALLOWED_MODULES))
        for line in lines)


def test_per_node_runner_runs_without_importing_sky(tmp_path):
    """Dynamic check: run the inlined runner in a fresh interpreter.

    Mirrors what a Ray worker executes: only the driver's stdlib imports and
    the inlined per-node functions; sky must stay out of sys.modules.
    """
    code = _build_driver(2, with_setup=False)
    imports = task_codegen.RayCodeGen()
    imports._add_common_imports()  # pylint: disable=protected-access
    runner_src = code[code.index('import importlib.util'):code.index(
        'run_task_script_with_log_and_return_pid = ray.remote(')]
    # The runner block also carries make_task_bash_script, which only the
    # driver calls; drop it to keep this program free of sky constants.
    runner_src = (runner_src[:runner_src.index('def make_task_bash_script')] +
                  runner_src[runner_src.index('def _start_subprocess_daemon'):])
    log_path = tmp_path / 'logs' / 'rank.log'
    script = ('echo out-line; echo err-line >&2; printf "crlf-line\\r\\n"; '
              'exit 3\n')
    program = (
        imports._code[0] + runner_src +  # pylint: disable=protected-access
        textwrap.dedent(f"""
        import json
        res = run_task_script_with_log_and_return_pid({script!r},
                                                      {str(log_path)!r})
        print('RESULT ' + json.dumps({{
            'res': res,
            'pid': os.getpid(),
            'sky_imported': any(m == 'sky' or m.startswith('sky.')
                                for m in sys.modules),
        }}))
        """))
    proc = subprocess.run([sys.executable, '-c', program],
                          cwd=_REPO_ROOT,
                          env=dict(os.environ, HOME=str(tmp_path)),
                          capture_output=True,
                          text=True,
                          timeout=60,
                          check=True)
    result_line = [
        line for line in proc.stdout.splitlines() if line.startswith('RESULT ')
    ]
    assert len(result_line) == 1, proc.stdout
    result = json.loads(result_line[0][len('RESULT '):])
    assert result['res'] == {'return_code': 3, 'pid': result['pid']}
    assert not result['sky_imported']
    # stderr is merged into the streamed stdout and the log, CRLF is
    # normalized, and bash -i's job-control warnings are dropped.
    expected = ['out-line', 'err-line', 'crlf-line']
    streamed = proc.stdout.splitlines()[:-1]
    logged = log_path.read_text().splitlines(keepends=True)
    for lines in (streamed, [l.rstrip('\n') for l in logged]):
        assert [l for l in lines if l in expected] == expected, lines
        assert not any('no job control' in l for l in lines)
    assert not any(l.endswith('\r\n') for l in logged)


@pytest.mark.parametrize('num_nodes', [1, 4])
def test_bundle_ips_come_from_gcs_not_check_ip_tasks(num_nodes):
    """No check_ip task fan-out after pg.ready(): the map is read from GCS."""
    code = _build_driver(num_nodes, with_setup=False)
    assert 'check_ip' not in code
    assert 'placement_group_table(\n    pg)[\'bundles_to_node_id\']' in code
    # The only remote calls are the per-node runner's, one per rank.
    assert code.count('.remote(') - code.count('ray.remote(') == num_nodes
